101	int gd32_bringup(void)
102	{
103	#ifdef CONFIG_GD32VW55X_I2C0
104	  struct i2c_master_s *i2c;
105	#endif
106	#ifdef CONFIG_GD32VW55X_SPI
107	  struct spi_dev_s *spi;
108	#endif
109	#ifdef CONFIG_GD32VW55X_ADC
110	  static const uint8_t chanlist[1] =
111	  {
112	#ifdef GPIO_ADC_IN0
113	    0   /* ADC_IN0 (PA1) on board header, routed by the adc example */
114	#else
115	    0   /* ADC_IN0; no analog pin routed, registers the device only */
116	#endif
117	  };
118	
119	  struct adc_dev_s *adc;
120	#endif
121	#ifdef CONFIG_GD32VW55X_PWM
122	  struct pwm_lowerhalf_s *pwm;
123	#endif
124	#ifdef CONFIG_GD32VW55X_CAPTURE
125	  struct cap_lowerhalf_s *cap;
126	#endif
127	#ifdef CONFIG_MTD_PROGMEM
128	  struct mtd_dev_s *mtd;
129	#endif
130	  int ret = OK;
131	
132	#ifdef CONFIG_GD32VW55X_WIFI
133	  /* Initialize the platform + the SDK Wi-Fi stack.  The SDK calls
134	   * net_if_add() when it creates the VIF, and that is where wlan0 is
135	   * registered.
136	   */
137	
138	  if (gdwifi_start() != 0)
139	    {
140	      ferr("ERROR: failed to start Wi-Fi\n");
141	    }
142	#endif
143	
144	#ifdef CONFIG_GD32VW55X_BLE
145	  /* After Wi-Fi: the platform (clocks, RF, NVDS) is brought up there, and
146	   * the BLE controller reuses it.
147	   */
148	
149	  if (gd32_ble_initialize() < 0)
150	    {
151	      ferr("ERROR: failed to start BLE\n");
152	    }
153	#endif
154	
155	#ifdef CONFIG_GD32VW55X_I2C0
156	  i2c = gd32_i2cbus_initialize(0);
157	  if (i2c == NULL)
158	    {
159	      ferr("ERROR: failed to initialize I2C0\n");
160	    }
161	  else
162	    {
163	#ifdef CONFIG_I2C_DRIVER
164	      /* Expose the bus as /dev/i2c0 for the i2ctool (i2c dev/get/set...) */
165	
166	      if (i2c_register(i2c, 0) < 0)
167	        {
168	          ferr("ERROR: failed to register /dev/i2c0\n");
169	        }
170	#endif
171	
172	#ifdef CONFIG_SENSORS_SHT3X
173	      /* Sensirion SHT3x on I2C0 -> /dev/temp0.  The default I2C address is
174	       * 0x44 (0x45 with ADDR tied high); confirm it first with
175	       * "i2c dev 0x44 0x45" from NSH.
176	       */
177	
178	      if (sht3x_register("/dev/temp0", i2c, 0x44) < 0)
179	        {
180	          ferr("ERROR: failed to register SHT3x at 0x44 on I2C0\n");
181	        }
182	#endif
183	    }
184	#endif
185	
186	#ifdef CONFIG_GD32VW55X_SPI
187	  /* The family has a single SPI instance: bus 0.  Configure the chip select
188	   * GPIOs first, then bring the bus up.
189	   */
190	
191	  gd32_spidev_initialize();
192	
193	  spi = gd32_spibus_initialize(0);
194	  if (spi == NULL)
195	    {
196	      ferr("ERROR: failed to initialize SPI0\n");
197	    }
198	  else
199	    {
200	#ifdef CONFIG_SPI_DRIVER
201	      if (spi_register(spi, 0) < 0)
202	        {
203	          ferr("ERROR: failed to register /dev/spi0\n");
204	        }
205	#endif
206	
207	#ifdef CONFIG_MMCSD_SPI
208	      /* Bind SPI0 to the MMC/SD SPI slot (/dev/mmcsd0) and mount it as FAT.
209	       * The SD card is wired to SPI0 (SCK PA11, MISO PA10, MOSI PA9) with the
210	       * chip select on PA12.
211	       */
212	
213	      ret = mmcsd_spislotinitialize(0, 0, spi);
214	      if (ret < 0)
215	        {
216	          ferr("ERROR: failed to bind SPI0 to the MMC/SD slot: %d\n", ret);
217	        }
218	      else
219	        {
220	          ret = nx_mount("/dev/mmcsd0", "/mnt/sd", "vfat", 0, NULL);
221	          if (ret < 0)
222	            {
223	              ferr("ERROR: failed to mount /mnt/sd: %d\n", ret);
224	            }
225	        }
226	#endif
227	    }
228	#endif
229	
230	#ifdef CONFIG_GD32VW55X_ADC
231	  adc = gd32_adc_initialize(0, chanlist, 1);
232	  if (adc == NULL)
233	    {
234	      ferr("ERROR: failed to initialize the ADC\n");
235	    }
236	  else if (adc_register("/dev/adc0", adc) < 0)
237	    {
238	      ferr("ERROR: failed to register /dev/adc0\n");
239	    }
240	#endif
241	
242	#ifdef CONFIG_GD32VW55X_PWM
243	  pwm = gd32_pwminitialize(1);
244	  if (pwm == NULL)
245	    {
246	      ferr("ERROR: failed to initialize PWM on TIMER1\n");
247	    }
248	  else if (pwm_register("/dev/pwm0", pwm) < 0)
249	    {
250	      ferr("ERROR: failed to register /dev/pwm0\n");
251	    }
252	#endif
253	
254	#ifdef CONFIG_GD32VW55X_CAPTURE
255	  cap = gd32_cap_initialize(2);
256	  if (cap == NULL)
257	    {
258	      ferr("ERROR: failed to initialize capture on TIMER2\n");
259	    }
260	  else if (cap_register("/dev/capture0", cap) < 0)
261	    {
262	      ferr("ERROR: failed to register /dev/capture0\n");
263	    }
264	#endif
265	
266	#ifdef CONFIG_MTD_PROGMEM
267	  /* The progmem region of the internal flash as an MTD device.  It sits
268	   * below the Wi-Fi NVDS -- see CONFIG_GD32VW55X_PROGMEM_START_ADDR.
269	   */
270	
271	  mtd = progmem_initialize();
272	  if (mtd == NULL)
273	    {
274	      ferr("ERROR: progmem_initialize failed\n");
275	    }
276	  else
277	    {
278	      ret = register_mtddriver("/dev/gd32flash", mtd, 0750, NULL);
279	      if (ret < 0)
280	        {
281	          ferr("ERROR: failed to register /dev/gd32flash: %d\n", ret);
282	        }
283	
284	#ifdef CONFIG_FS_LITTLEFS
285	      /* Mount it as LittleFS, formatting it on the first boot */
286	
287	      else
288	        {
289	          ret = nx_mount("/dev/gd32flash", "/data", "littlefs", 0,
290	                         "autoformat");
291	          if (ret < 0)
292	            {
293	              ferr("ERROR: failed to mount /data: %d\n", ret);
294	            }
295	        }
296	#endif
297	    }
298	#endif
299	
300	#ifdef CONFIG_USERLED_LOWER
301	  /* The three board LEDs -> /dev/userleds */
302	
303	  ret = userled_lower_initialize("/dev/userleds");
304	  if (ret < 0)
305	    {
306	      ferr("ERROR: failed to register /dev/userleds: %d\n", ret);
307	    }
308	#endif
309	
310	#ifdef CONFIG_GD32VW55X_FWDGT
311	  gd32_fwdgt_initialize("/dev/watchdog0", BOARD_IRC32K_FREQUENCY);
312	#endif
313	
314	#ifdef CONFIG_GD32VW55X_WWDGT
315	  gd32_wwdgt_initialize("/dev/watchdog1");
316	#endif
317	
318	#ifdef CONFIG_BOARD_LCD_ENABLE
319	  /* Initialize the LCD and register /dev/lcd0 */
320	
321	  ret = board_lcd_initialize();
322	  if (ret < 0)
323	    {
324	      ferr("ERROR: board_lcd_initialize failed: %d\n", ret);
325	    }
326	#endif
327	
328	#ifdef CONFIG_FS_PROCFS
329	  /* Mount the procfs file system */
330	
331	  ret = nx_mount(NULL, "/proc", "procfs", 0, NULL);
332	  if (ret < 0)
333	    {
334	      ferr("ERROR: Failed to mount procfs at /proc: %d\n", ret);
335	    }
336	#endif
337	
338	  return ret;
339	}
