2016	    \param[in]  none
2017	    \param[out] none
2018	    \retval     0 on success and != 0 if error occured.
2019	*/
2020	int wifi_management_disconnect(void)
2021	{
2022	    uint8_t vif_idx = WIFI_VIF_INDEX_DEFAULT;
2023	    struct wifi_vif_tag *wvif = &wifi_vif_tab[vif_idx];
2024	    struct wifi_sta *sta = &(wvif->sta);
2025	    int ret = 0;
2026	
2027	    WIFI_CLOSED_CHECK(1);
2028	
2029	    if (wvif->wvif_type == WVIF_STA) {
2030	        /* Flush wait queue */
2031	        mgmt_wait_queue_flush();
2032	
2033	        if (eloop_event_send(vif_idx, WIFI_MGMT_EVENT_DISCONNECT_CMD)) {
2034	            netlink_printf("MGMT: DISCONNECT_CMD, eloop event queue full\r\n");
2035	            return -1;
2036	        }
2037	
2038	        ret = mgmt_wait_queue_fetch(vif_idx, MGMT_WAIT_EVT_DISCONN_DONE, 10000);
2039	        if (ret != 0)
2040	            netlink_printf("MGMT: wait disconnect done timeout, ret %d\r\n", ret);
2041	        else
2042	            netlink_printf("MGMT: disconnect complete\r\n");
2043	        sta->last_reason = 0;
2044	    } else {
2045	        netlink_printf("MGMT: not station mode, do nothing\r\n");
2046	    }
2047	
2048	    return ret;
2049	}
